<script>
document.addEventListener('DOMContentLoaded', () => {
  const filters=document.querySelectorAll('.notification-filter'), cards=document.querySelectorAll('.notification-card'), groups=document.querySelectorAll('[data-notification-group]'), empty=document.getElementById('noNotifications');
  function filterNotifications(filter){let visible=0;cards.forEach(card=>{const show=filter==='all'||card.dataset.notification.includes(filter);card.classList.toggle('hidden',!show);if(show)visible++;});groups.forEach(group=>group.classList.toggle('hidden',!group.querySelector('.notification-card:not(.hidden)')));empty.classList.toggle('hidden',visible>0);filters.forEach(button=>{const active=button.dataset.notificationFilter===filter;button.classList.toggle('bg-[#0b2545]',active);button.classList.toggle('text-white',active);button.classList.toggle('text-gray-500',!active);button.classList.toggle('dark:text-gray-300',!active);});}
  filters.forEach(button=>button.addEventListener('click',()=>filterNotifications(button.dataset.notificationFilter)));
  document.getElementById('markAllPageRead').addEventListener('click',function(){document.querySelectorAll('.notification-card').forEach(card=>{card.dataset.notification=card.dataset.notification.replace(' unread','');card.classList.remove('bg-sky-50/55','dark:bg-sky-950/20','border-sky-100','dark:border-sky-900/60');card.classList.add('bg-white','dark:bg-[#0c1f36]','border-gray-200','dark:border-gray-700');});document.querySelectorAll('.unread-dot').forEach(dot=>dot.remove());this.innerHTML='<i data-lucide="check-check" class="w-4 h-4 text-emerald-500"></i> You are all caught up';lucide.createIcons();filterNotifications('all');});
});
</script>
<script>
document.addEventListener('DOMContentLoaded', async () => {
  const token=localStorage.getItem('flow_token')||''; const feed=document.getElementById('notificationFeed');
  try { const response=await fetch('../api/notifications/list.php',{headers:{Authorization:`Bearer ${token}`}}); const data=await response.json(); if(!response.ok||!data.success) throw new Error(data.error||'Unable to load notifications');
    feed.innerHTML=''; const items=data.notifications||[]; document.querySelectorAll('.notification-filter span').forEach((el,i)=>{ if(i===0) el.textContent=items.length; if(i===1) el.textContent=data.unread_count||0; });
    if(!items.length){ document.getElementById('noNotifications').classList.remove('hidden'); return; }
    items.forEach(item=>{ const card=document.createElement('article'); card.className='notification-card flex gap-4 rounded-2xl border border-gray-200 dark:border-gray-700 bg-white dark:bg-[#0c1f36] p-4 sm:p-5'; card.dataset.notification=`${item.type||'system'}${item.read?'':' unread'}`; const content=document.createElement('div'); content.className='min-w-0 flex-1'; const heading=document.createElement('h3'); heading.className='font-bold text-gray-900 dark:text-white'; heading.textContent=item.title||'Notification'; const body=document.createElement('p'); body.className='mt-1 text-sm text-gray-500 dark:text-gray-300'; body.textContent=item.body||''; const time=document.createElement('time'); time.className='text-xs text-gray-400'; time.textContent=item.created_at||''; content.append(heading,body,time); card.append(content); if(!item.read){const dot=document.createElement('span');dot.className='unread-dot mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full bg-sky-500';card.append(dot);} card.addEventListener('click',async()=>{if(!item.read){await fetch('../api/notifications/mark-read.php',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({id:item.id})});}}); feed.append(card); });
  } catch(error) { feed.innerHTML='<p class="py-16 text-center text-sm text-gray-500">Unable to load notifications right now.</p>'; }
});
</script>
